text:
  "tStartMs": 941790,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "這樣的一個政經中心"
  } ]
}, {
  "tStartMs": 943592,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "那事實上我內心就有個想法"
  } ]
}, {
  "tStartMs": 945694,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "說等我走完東海道"
  } ]
}, {
  "tStartMs": 947196,
  "dDurationMs": 1818,
  "segs": [ {
    "utf8": "我想要回來走走台一線 "
  } ]
}, {
  "tStartMs": 949014,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "或者是台三線"
  } ]
}, {
  "tStartMs": 950399,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "把那些記憶把它收藏起來"
  } ]
}, {
  "tStartMs": 952701,
  "dDurationMs": 2303,
  "segs": [ {
    "utf8": "我相信這樣大家就會很有感覺"
  } ]
}, {
  "tStartMs": 955004,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "要找到一個共同的主題"
  } ]
}, {
  "tStartMs": 956605,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "那我們剛剛講到的是"
  } ]
}, {
  "tStartMs": 958190,
  "dDurationMs": 2803,
  "segs": [ {
    "utf8": "有一些不同的族群群體"
  } ]
}, {
  "tStartMs": 960993,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "甚至地區的回憶"
  } ]
}, {
  "tStartMs": 962594,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "可是說真的"
  } ]
}, {
  "tStartMs": 963495,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "我覺得在這個社會上 "
  } ]
}, {
  "tStartMs": 964680,
  "dDurationMs": 1518,
  "segs": [ {
    "utf8": "還存在一種世代"
  } ]
}, {
  "tStartMs": 966198,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "像我們剛剛講到說"
  } ]
}, {
  "tStartMs": 967199,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "日本像以前有一些共同的歌曲"
  } ]
}, {
  "tStartMs": 969601,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "甚至有些喫茶店"
  } ]
}, {
  "tStartMs": 971003,
  "dDurationMs": 1418,
  "segs": [ {
    "utf8": "然後去的時候 "
  } ]
}, {
  "tStartMs": 972421,
  "dDurationMs": 2169,
  "segs": [ {
    "utf8": "有所謂的昭和時代的風景"
  } ]
}, {
  "tStartMs": 974590,
  "dDurationMs": 2602,
  "segs": [ {
    "utf8": "那像我的年紀正好介於"
  } ]
}, {
  "tStartMs": 977192,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "我們就說偉忠哥跟你之間"
  } ]
}, {
  "tStartMs": 979294,
  "dDurationMs": 2203,
  "segs": [ {
    "utf8": "我之前就稍微想了一下說"
  } ]
}, {
  "tStartMs": 981497,
  "dDurationMs": 1918,
  "segs": [ {
    "utf8": "好 因為像之前訪問你的 "
  } ]
}, {
  "tStartMs": 983415,
  "dDurationMs": 1285,
  "segs": [ {
    "utf8": "偉忠哥也好"
  } ]
}, {
  "tStartMs": 984700,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "李四端先生"
  } ]
}, {
  "tStartMs": 985801,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "他們都是屬於媒體新聞的前輩"
  } ]
}, {
  "tStartMs": 988103,
  "dDurationMs": 2303,
  "segs": [ {
    "utf8": "那他們大概大我一個世代"
  } ]
}, {
  "tStartMs": 990406,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "對 沒有錯"
  } ]
}, {
  "tStartMs": 991490,
  "dDurationMs": 2019,
  "segs": [ {
    "utf8": "然後你大概跟我差距 "
  } ]
}, {
  "tStartMs": 993509,
  "dDurationMs": 2185,
  "segs": [ {
    "utf8": "就是大概一輪"
  } ]
}, {
  "tStartMs": 995694,
  "dDurationMs": 2603,
  "segs": [ {
    "utf8": "所以我是屬於那種五年級中段班"
  } ]
}, {
  "tStartMs": 998297,
  "dDurationMs": 784,
  "segs": [ {
    "utf8": "我必須說 "
  } ]
}, {
  "tStartMs": 999081,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "五年級這個世代"
  } ]
}, {
  "tStartMs": 1000399,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "我感覺現在是一種"
  } ]
}, {
  "tStartMs": 1002001,
  "dDurationMs": 884,
  "segs": [ {
    "utf8": "有一點失落 "
  } ]
}, {
  "tStartMs": 1002885,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "有一點寂寞"
  } ]
}, {
  "tStartMs": 1004103,
  "dDurationMs": 700,
  "segs": [ {
    "utf8": "因為為什麼"
  } ]
}, {
  "tStartMs": 1004803,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "因為我們年輕的時候"
  } ]
}, {
  "tStartMs": 1006305,
  "dDurationMs": 4388,
  "segs": [ {
    "utf8": "受到的還是屬於愛國教育之類的"
  } ]
}, {
  "tStartMs": 1010693,
  "dDurationMs": 800,
  "segs": [ {
    "utf8": "當時所學"
  } ]
}, {
  "tStartMs": 1011493,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "我是在末端嗎"
  } ]
}, {
  "tStartMs": 1012294,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "因為我七一"
  } ]
}, {
  "tStartMs": 1013295,
  "dDurationMs": 401,
  "segs": [ {
    "utf8": "有吧"
  } ]
}, {
  "tStartMs": 1013696,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "所以我在末端"
  } ]
}, {
  "tStartMs": 1014797,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "當時讀到的歷史"
  } ]
}, {
  "tStartMs": 1016198,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "好像跟後來的詮釋都不太一樣"
  } ]
}, {
  "tStartMs": 1018400,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "我記得前幾次"
  } ]
}, {
  "tStartMs": 1019585,
  "dDurationMs": 1518,
  "segs": [ {
    "utf8": " 我忘了是哪一次的選舉"
  } ]
}, {
  "tStartMs": 1021103,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "好像那個時候就拍一個影片"
  } ]
}, {
  "tStartMs": 1023005,
  "dDurationMs": 1868,
  "segs": [ {
    "utf8": "然後甚至於拍成一個電影"
  } ]
}, {
  "tStartMs": 1024873,
  "dDurationMs": 2720,
  "segs": [ {
    "utf8": "就在描寫所謂的五年級世代"
  } ]
}, {
  "tStartMs": 1027593,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "我們為什麼以前 "
  } ]
}, {
  "tStartMs": 1028711,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "我們認為對的事情"
  } ]
}, {
  "tStartMs": 1029795,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "現在都變錯了"
  } ]
}, {
  "tStartMs": 1031196,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "然後我們好像被社會上"
  } ]
}, {
  "tStartMs": 1032598,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "成為被忽略的一代"
  } ]
}, {
